from datetime import date, timedelta
import calendar

_WD = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def recur(start: str, rule: str, count: int) -> list[str]:
    sy, sm, sd = (int(p) for p in start.split("-"))
    start_d = date(sy, sm, sd)
    parts = rule.split()
    kind = parts[0]
    k = int(parts[1])
    out: list[str] = []

    if kind == "DAILY":
        for i in range(count):
            out.append((start_d + timedelta(days=i * k)).isoformat())
        return out

    if kind == "WEEKLY":
        wanted = sorted(_WD[c] for c in parts[2].split(","))
        monday0 = start_d - timedelta(days=start_d.weekday())
        step = 0
        while len(out) < count:
            monday = monday0 + timedelta(weeks=step * k)
            for wd in wanted:
                dt = monday + timedelta(days=wd)
                if dt >= start_d:
                    out.append(dt.isoformat())
                    if len(out) == count:
                        break
            step += 1
        return out

    if kind == "MONTHLY":
        base = sy * 12 + (sm - 1)
        if len(parts) == 3:
            dom = int(parts[2])
            step = 0
            while len(out) < count:
                y, m0 = divmod(base + step * k, 12)
                m = m0 + 1
                last = calendar.monthrange(y, m)[1]
                if dom == -1:
                    dt = date(y, m, last)
                elif dom <= last:
                    dt = date(y, m, dom)
                else:
                    dt = None
                if dt is not None and dt >= start_d:
                    out.append(dt.isoformat())
                step += 1
            return out

        nth = int(parts[2])
        wd = _WD[parts[3]]
        step = 0
        while len(out) < count:
            y, m0 = divmod(base + step * k, 12)
            m = m0 + 1
            last = calendar.monthrange(y, m)[1]
            if nth == -1:
                dt = date(y, m, last)
                dt -= timedelta(days=(dt.weekday() - wd) % 7)
            else:
                first = date(y, m, 1)
                day = 1 + (wd - first.weekday()) % 7 + (nth - 1) * 7
                dt = date(y, m, day) if day <= last else None
            if dt is not None and dt >= start_d:
                out.append(dt.isoformat())
            step += 1
        return out

    mm_s, dd_s = parts[2].split("-")
    mm, dd = int(mm_s), int(dd_s)
    step = 0
    while len(out) < count:
        y = sy + step * k
        try:
            dt = date(y, mm, dd)
        except ValueError:
            dt = None
        if dt is not None and dt >= start_d:
            out.append(dt.isoformat())
        step += 1
    return out
